import { Box, Flex, Separator, Tag, Text } from "@chakra-ui/react";
import { useMemo, useState } from "react";
import { InspectorViewHeader } from "../../components/InspectorViewHeader";
import { useIsLargeScreen } from "../../hooks/useIsLargeScreen";
import { NoData } from "../../Placeholder";
import { selectSkillForSelectedElement, useInspectorStore } from "../../store";
import { PlaceholderImage } from "../../types";
import { InspectorView } from "../../types/inspector";
import { ProseSegments } from "./ProseSegments";
import { ReferenceTag } from "./ReferenceTag";
import { SkillBlockSection } from "./SkillBlockSection";
import { SkillMarkdown } from "./SkillMarkdown";
import { useResolvedSkillState } from "./useResolvedSkillState";
import { buildMemoryReferenceIndex, buildReferenceIndex } from "./references";
import { flowStepTrail } from "../../utils";

function pendingSkillBadge(label: string | null) {
  if (!label) return undefined;
  return (
    <Tag.Root
      colorPalette="yellow"
      variant="subtle"
      size="sm"
      rounded="full"
      data-testid="pending-skill-tag"
    >
      <Tag.Label>{label}</Tag.Label>
    </Tag.Root>
  );
}

/**
 * Middle pane for skill-based (Mantle) projects: renders the active skill
 * as its authored document — prose sections (markdown, references
 * highlighted, `if:`-scoped paragraphs muted when unmet) interleaved with
 * ordered-block cards.
 */
export function SkillSection() {
  // While an element is selected the pane travels to the skill active then (with
  // its step highlighted); otherwise the live active skill.
  const activeSkill = useInspectorStore(selectSkillForSelectedElement);
  const skillCatalog = useInspectorStore((s) => s.skillCatalog);
  const inspectorView = useInspectorStore((s) => s.inspectorView);
  const selectedElement = useInspectorStore((s) => s.selectedElement);
  const pendingSkills = useInspectorStore((s) => s.skillState?.pending_skills ?? []);

  const {
    isHistorical,
    evaluatedConditions,
    toolGateStatuses,
    blockStatuses,
    conditionMemory,
    flowId,
    stepId,
    events,
    anchorIndex,
  } = useResolvedSkillState(activeSkill);

  const isLargeScreen = useIsLargeScreen();
  // Same rule as the flow canvas: the All layout shows every pane at once,
  // so the view switcher is redundant there.
  const showViewSwitcher = !(isLargeScreen && inspectorView === InspectorView.All);

  const references = useMemo(() => {
    if (!activeSkill || !skillCatalog) return new Map();
    const base = buildReferenceIndex(activeSkill.skill, skillCatalog);
    const memRefs = buildMemoryReferenceIndex(conditionMemory ?? undefined);
    // Merge: memory references are added; on collision base wins (tool > memory).
    const merged = new Map(base);
    for (const [key, ref] of memRefs) {
      if (!merged.has(key)) merged.set(key, ref);
    }
    return merged;
  }, [activeSkill, skillCatalog, conditionMemory]);

  // Accordion: the block running the active flow expands by default; user
  // toggles override until the active flow moves on. Toggles are keyed to the
  // flow they were made under, so a flow change discards them without an effect.
  const activeFlowId = flowId;
  const [manualToggles, setManualToggles] = useState<{
    flowId: string | null;
    toggles: Record<string, boolean>;
  }>({ flowId: null, toggles: {} });
  const manuallyToggled = manualToggles.flowId === activeFlowId ? manualToggles.toggles : {};

  // Ordered step trail per block flow id, reconstructed from the dialogue-stack
  // updates up to the anchor (the same source the CALM flow canvas uses). The
  // stack carries the active step on every update, so this captures every step
  // the block passed through — including transient execute/set steps that emit
  // no step-stamped event of their own. Deriving it from individual event
  // stepIds misses those and collapses the trail to the resting step alone.
  const stepTrailsByFlowId = useMemo(() => {
    const limit = Math.min(anchorIndex + 1, events.length);
    return flowStepTrail(events.slice(0, limit));
  }, [events, anchorIndex]);

  // Every id a call: step may target — block flow ids plus skill ids.
  const callTargetIds = useMemo(() => {
    if (!skillCatalog) return [];
    const ids = Object.keys(skillCatalog);
    for (const catalogSkill of Object.values(skillCatalog)) {
      ids.push(...Object.values(catalogSkill.blocks).map((block) => block.ordered_block_id));
    }
    return ids;
  }, [skillCatalog]);

  const pendingLabel =
    selectedElement || pendingSkills.length === 0
      ? null
      : `Pending: ${pendingSkills.map((item) => item.name ?? item.skill_id).join(", ")}`;

  if (!activeSkill) {
    return (
      <Flex direction="column" height="100%">
        <InspectorViewHeader
          title="Active skill: "
          text="—"
          showViewSwitcher={showViewSwitcher}
          badge={pendingSkillBadge(pendingLabel)}
        />
        <NoData
          image={PlaceholderImage.NoFlow}
          shortLabel="No skill is currently active"
          longLabel="Type a message to talk to the latest trained version of your assistant"
        />
      </Flex>
    );
  }

  const { skill } = activeSkill;
  const headerText = isHistorical
    ? `${skill.name ?? skill.id} (at selected message)`
    : (skill.name ?? skill.id);

  return (
    <Flex direction="column" height="100%">
      <InspectorViewHeader
        title="Active skill: "
        text={headerText}
        showViewSwitcher={showViewSwitcher}
        badge={pendingSkillBadge(pendingLabel && !isHistorical ? pendingLabel : null)}
      />
      {/* The 768px cap lives on the pane (TryAssistant's middle column), so the
          panels sit together on wide monitors; the document fills the pane. */}
      <Flex flex="1" minHeight={0} overflowY="auto" data-testid="skill-section">
        <Flex direction="column" width="100%" px="6" py="6" gap="5">
          {/* The skill name lives in the pane header ("Active skill: …"). */}
          {skill.description ? (
            <Box color="fg.muted">
              <SkillMarkdown
                text={skill.description}
                references={references}
                memory={conditionMemory}
              />
            </Box>
          ) : null}

          {skill.sections.map((section, sectionIndex) => {
            if (section.type === "prose") {
              return (
                <ProseSegments
                  // Sections are static per catalog load; index is a stable key.
                  key={sectionIndex}
                  section={section}
                  references={references}
                  evaluatedConditions={evaluatedConditions}
                  memory={conditionMemory}
                />
              );
            }
            const block = skill.blocks[section.block_id];
            const expanded =
              manuallyToggled[section.block_id] ??
              (block ? block.ordered_block_id === flowId : false);
            const blockStepTrail = block ? (stepTrailsByFlowId[block.ordered_block_id] ?? []) : [];
            return (
              <SkillBlockSection
                key={section.block_id}
                skill={skill}
                blockId={section.block_id}
                callTargetIds={callTargetIds}
                blockStatuses={blockStatuses}
                activeFlowId={flowId}
                activeStepId={stepId}
                stepTrail={blockStepTrail}
                expanded={expanded}
                onToggle={() =>
                  setManualToggles({
                    flowId: activeFlowId,
                    toggles: { ...manuallyToggled, [section.block_id]: !expanded },
                  })
                }
              />
            );
          })}

          {skill.tool_names.length > 0 || skill.referenced_skills.length > 0 ? (
            <>
              <Separator />
              <Flex direction="column" gap="3">
                {skill.tool_names.length > 0 ? (
                  <Flex
                    gap="2"
                    alignItems="center"
                    flexWrap="wrap"
                    data-testid="skill-available-tools"
                  >
                    <Text textStyle="sm" flexShrink={0}>
                      Available tools
                    </Text>
                    {skill.tool_names.map((toolName) => (
                      <ReferenceTag
                        key={toolName}
                        name={toolName}
                        reference={{ kind: "tool", target: toolName }}
                        disabled={toolGateStatuses?.[toolName]?.active === false}
                      />
                    ))}
                  </Flex>
                ) : null}
                {skill.referenced_skills.length > 0 ? (
                  <Flex gap="2" alignItems="center" flexWrap="wrap" data-testid="skill-references">
                    <Text textStyle="sm" flexShrink={0}>
                      References
                    </Text>
                    {skill.referenced_skills.map((skillId) => (
                      <ReferenceTag
                        key={skillId}
                        name={skillId}
                        reference={{ kind: "skill", target: skillId }}
                      />
                    ))}
                  </Flex>
                ) : null}
              </Flex>
            </>
          ) : null}
        </Flex>
      </Flex>
    </Flex>
  );
}
